package com.gauntletguard;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GauntletGuardConfig.GROUP)
public interface GauntletGuardConfig extends Config
{
	String GROUP = "gauntlet-food-warning";

	@ConfigItem(
		keyName = "warnRawFood",
		name = "Warn about raw food",
		description = "Warn when entering the boss room with raw paddlefish"
	)
	default boolean warnRawFood()
	{
		return true;
	}

	@ConfigItem(
		keyName = "warnUnfinishedPotions",
		name = "Warn about unfinished potions",
		description = "Warn when entering the boss room with unfinished Grym potions"
	)
	default boolean warnUnfinishedPotions()
	{
		return true;
	}
}

package com.gauntletguard;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Gauntlet Guard",
	description = "Warns when entering the Hunllef room with unfinished supplies",
	tags = {"gauntlet", "corrupted", "hunllef", "food", "paddlefish", "potion"}
)
public class GauntletGuardPlugin extends Plugin
{
	static final String RAW_FOOD_WARNING = "Warning: You still have raw paddlefish in your inventory!";
	static final String UNFINISHED_POTION_WARNING = "Warning: You still have unfinished Grym potions in your inventory!";

	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private GauntletGuardConfig config;

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!isBossRoomEntry(event.getMenuOption(), event.getMenuTarget()))
		{
			return;
		}

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}

		Item[] items = inventory.getItems();
		boolean shouldBlock = false;

		if (config.warnRawFood() && containsRawPaddlefish(items))
		{
			warn(RAW_FOOD_WARNING);
			shouldBlock = true;
		}

		if (config.warnUnfinishedPotions() && containsUnfinishedPotion(items))
		{
			warn(UNFINISHED_POTION_WARNING);
			shouldBlock = true;
		}

		if (shouldBlock)
		{
			event.consume();
		}
	}

	private void warn(String message)
	{
		client.addChatMessage(
			ChatMessageType.GAMEMESSAGE,
			"",
			"<col=ff0000>" + message + "</col>",
			null
		);
		notifier.notify(message);
	}

	static boolean isBossRoomEntry(String option, String target)
	{
		if (option == null || target == null)
		{
			return false;
		}

		String cleanTarget = Text.removeTags(target).toLowerCase();

		boolean enterBossRoom = "enter".equalsIgnoreCase(option)
			&& (cleanTarget.contains("boss room") || cleanTarget.contains("hunllef"));

		boolean passBarrier = ("pass".equalsIgnoreCase(option) || "quick-pass".equalsIgnoreCase(option))
			&& cleanTarget.contains("barrier");

		return enterBossRoom || passBarrier;
	}

	static boolean containsRawPaddlefish(Item[] items)
	{
		for (Item item : items)
		{
			if (item.getId() == ItemID.GAUNTLET_RAW_FOOD)
			{
				return true;
			}
		}

		return false;
	}

	static boolean containsUnfinishedPotion(Item[] items)
	{
		for (Item item : items)
		{
			if (item.getId() == ItemID.GAUNTLET_POTION_UNFINISHED)
			{
				return true;
			}
		}

		return false;
	}

	@Provides
	GauntletGuardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GauntletGuardConfig.class);
	}
}

package com.gauntletguard;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GauntletGuardPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GauntletGuardPlugin.class);
		RuneLite.main(args);
	}
}

package com.gauntletguard;

import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GauntletGuardTest
{
	@Test
	public void identifiesBossRoomEntry()
	{
		assertTrue(GauntletGuardPlugin.isBossRoomEntry("Enter", "<col=ffff>Boss room</col>"));
		assertTrue(GauntletGuardPlugin.isBossRoomEntry("Enter", "Crystalline Hunllef"));
		assertFalse(GauntletGuardPlugin.isBossRoomEntry("Enter", "The Gauntlet"));
		assertFalse(GauntletGuardPlugin.isBossRoomEntry("Open", "Boss room"));
	}

	@Test
	public void identifiesPassBarrierEntry()
	{
		assertTrue(GauntletGuardPlugin.isBossRoomEntry("Pass", "Barrier"));
	}

	@Test
	public void identifiesQuickPassBarrierEntry()
	{
		assertTrue(GauntletGuardPlugin.isBossRoomEntry("Quick-pass", "<col=ffff>Barrier"));
	}

	@Test
	public void identifiesRawPaddlefish()
	{
		assertTrue(GauntletGuardPlugin.containsRawPaddlefish(new Item[]
		{
			new Item(ItemID.GAUNTLET_RAW_FOOD, 1)
		}));
		assertFalse(GauntletGuardPlugin.containsRawPaddlefish(new Item[]
		{
			new Item(ItemID.GAUNTLET_FOOD, 10)
		}));
	}

	@Test
	public void identifiesUnfinishedPotions()
	{
		assertTrue(GauntletGuardPlugin.containsUnfinishedPotion(new Item[]
		{
			new Item(ItemID.GAUNTLET_POTION_UNFINISHED, 1)
		}));
		assertFalse(GauntletGuardPlugin.containsUnfinishedPotion(new Item[]
		{
			new Item(ItemID.GAUNTLET_POTION_4, 1)
		}));
	}
}
